<?php
declare(strict_types=1);
if(!defined('_GNUBOARD_')){http_response_code(403);exit;}
require_once __DIR__.'/taxonomy-store.php';
function nt_admin_save(PDO $db,array $b,string $actor):array{
 $action=$b['action']??'';$id=(string)($b['id']??'');$reason=trim((string)($b['reason']??''));if($reason===''||strlen($reason)>500)throw new InvalidArgumentException('변경 사유를 입력하세요.');
 if(!(int)$db->query("SELECT GET_LOCK('noa_taxonomy_writer',0)")->fetchColumn())throw new DomainException('다른 분류 작업이 진행 중입니다.');
 try{$db->beginTransaction();
  if($action==='save_category'){
   if(!preg_match('/^[a-z0-9][a-z0-9-]{0,59}$/D',$id))throw new InvalidArgumentException('카테고리 ID 오류');$name=trim((string)($b['name']??''));$parent=$b['parent']?:null;if($name===''||mb_strlen($name)>120)throw new InvalidArgumentException('카테고리 이름 오류');$cats=array_column(nt_categories($db),null,'category_id');$walk=$parent;$seen=[$id=>true];while($walk!==null){if(isset($seen[$walk])||!isset($cats[$walk]))throw new DomainException('상위 카테고리가 없거나 순환 관계입니다.');$seen[$walk]=true;$walk=$cats[$walk]['parent_id'];}
   $old=$cats[$id]??null;if((int)($b['revision']??0)!==(int)($old['revision']??0))throw new DomainException('다른 관리자가 수정했습니다. 새로고침하세요.');
   $sort=filter_var($b['sort']??0,FILTER_VALIDATE_INT);if($sort===false||abs($sort)>100000)throw new InvalidArgumentException('정렬 순서 오류');$enabled=empty($b['enabled'])?0:1;
   if($old){$q=$db->prepare('UPDATE noa_categories SET parent_id=?,name=?,sort_order=?,enabled=?,revision=revision+1 WHERE category_id=?');$q->execute([$parent,$name,$sort,$enabled,$id]);}else{$q=$db->prepare('INSERT INTO noa_categories(category_id,parent_id,name,sort_order,enabled) VALUES(?,?,?,?,?)');$q->execute([$id,$parent,$name,$sort,$enabled]);}
  }elseif($action==='save_rule'){
   if(!preg_match('/^[a-zA-Z0-9:_-]{1,64}$/D',$id))throw new InvalidArgumentException('규칙 ID 오류');$c=$b['condition']??[];nt_rule_valid($c);$q=$db->prepare('SELECT * FROM noa_classification_rules WHERE rule_id=? FOR UPDATE');$q->execute([$id]);$old=$q->fetch(PDO::FETCH_ASSOC);if((int)($b['revision']??0)!==(int)($old['revision']??0))throw new DomainException('revision_conflict');
   $priority=filter_var($b['priority']??100,FILTER_VALIDATE_INT);if($priority===false||$priority<0||$priority>100000)throw new InvalidArgumentException('우선순위 오류');$name=trim((string)($b['name']??$id));if($name===''||mb_strlen($name)>160)throw new InvalidArgumentException('규칙 이름 오류');$cat=(string)($b['category']??'');$q=$db->prepare('SELECT COUNT(*) FROM noa_categories WHERE category_id=?');$q->execute([$cat]);if(!$q->fetchColumn())throw new InvalidArgumentException('카테고리 오류');
   if($old){$q=$db->prepare('UPDATE noa_classification_rules SET name=?,category_id=?,conditions=?,priority=?,enabled=?,revision=revision+1,updated_by=? WHERE rule_id=?');$q->execute([$name,$cat,nt_json($c),$priority,empty($b['enabled'])?0:1,$actor,$id]);}else{$q=$db->prepare('INSERT INTO noa_classification_rules(rule_id,name,category_id,conditions,priority,enabled,updated_by) VALUES(?,?,?,?,?,?,?)');$q->execute([$id,$name,$cat,nt_json($c),$priority,empty($b['enabled'])?0:1,$actor]);}
  }elseif($action==='save_production_rule'){
   $q=$db->prepare('SELECT * FROM noa_production_rules WHERE rule_id=? FOR UPDATE');$q->execute([$id]);$old=$q->fetch(PDO::FETCH_ASSOC);if(!$old)throw new InvalidArgumentException('unknown_rule');if((int)($b['revision']??0)!==(int)$old['revision'])throw new DomainException('revision_conflict');$body=$b['body']??'';if(!is_string($body)||trim($body)===''||strlen($body)>200000)throw new InvalidArgumentException('규칙 본문 오류');if($old['format']==='json'&&!is_array(json_decode($body,true,512,JSON_THROW_ON_ERROR)))throw new InvalidArgumentException('JSON 규칙 형식 오류');$sha=hash('sha256',$body);
   if($sha!==$old['sha256']){$rev=(int)$old['revision']+1;$q=$db->prepare('UPDATE noa_production_rules SET body=?,sha256=?,revision=?,updated_by=? WHERE rule_id=?');$q->execute([$body,$sha,$rev,$actor,$id]);$q=$db->prepare('INSERT INTO noa_production_rule_revisions(rule_id,revision,body,sha256,actor,reason) VALUES(?,?,?,?,?,?)');$q->execute([$id,$rev,$body,$sha,$actor,$reason]);}
  }elseif($action==='confirm'){
   $type=$b['type']??'';if(!in_array($type,['song','video','playlist'],true)||strlen($id)>100)throw new InvalidArgumentException('콘텐츠 오류');$cats=$b['categories']??[];if(!is_array($cats)||count($cats)>20)throw new InvalidArgumentException('카테고리 오류');
   $known=$type==='song'?ny_songs($db,ny_batch($db)):[];$run=ny_latest($db);if($type==='video')$known=ny_videos($db,$run,false);if($type==='playlist'){$q=$db->prepare('SELECT playlist_id FROM noa_youtube_playlists WHERE run_id=? AND playlist_id=?');$q->execute([$run['run_id'],$id]);$known=$q->fetchColumn()?[$id=>true]:[];}if(!isset($known[$id]))throw new InvalidArgumentException('등록된 콘텐츠가 아닙니다.');
   $q=$db->prepare('SELECT revision FROM noa_content_categories WHERE content_type=? AND content_id=? FOR UPDATE');$q->execute([$type,$id]);$revision=array_sum($q->fetchAll(PDO::FETCH_COLUMN));if((int)($b['revision']??0)!==$revision)throw new DomainException('revision_conflict');
   $q=$db->prepare('UPDATE noa_content_categories SET active=0,revision=revision+1 WHERE content_type=? AND content_id=?');$q->execute([$type,$id]);foreach(array_unique($cats)as $cat){$q=$db->prepare("INSERT INTO noa_content_categories(content_type,content_id,category_id,source,evidence,updated_by) VALUES(?,?,?,'manual',?,?) ON DUPLICATE KEY UPDATE source='manual',active=1,evidence=VALUES(evidence),updated_by=VALUES(updated_by),revision=revision+1");$q->execute([$type,$id,$cat,nt_json(['reason'=>$reason]),$actor]);}
   if($type==='video'&&!empty($b['songId'])){$songs=ny_songs($db,ny_batch($db));$sid=$b['songId'];if(!isset($songs[$sid]))throw new InvalidArgumentException('곡 ID 오류');$v=$known[$id];if(($v['match']['status']??'')==='rejected'||(!empty($v['match']['songId'])&&$v['match']['songId']!==$sid))throw new DomainException('기존 확정/거절 매칭은 YouTube 관리에서 먼저 검토하세요.');$q=$db->prepare("INSERT INTO noa_content_matches(video_id,song_id,status,source,evidence,updated_by) VALUES(?,?,'manual','manual',?,?) ON DUPLICATE KEY UPDATE song_id=VALUES(song_id),status='manual',source='manual',evidence=VALUES(evidence),revision=revision+1,updated_by=VALUES(updated_by)");$q->execute([$id,$sid,nt_json(['reason'=>$reason]),$actor]);}
  }else throw new InvalidArgumentException('unknown_action');
  nt_log($db,null,$action,$id,'administrator_change',['before'=>$old??null,'after'=>$b,'reason'=>$reason],$actor);$db->commit();return ['ok'=>true];
 }catch(Throwable $e){if($db->inTransaction())$db->rollBack();throw $e;}finally{$db->query("SELECT RELEASE_LOCK('noa_taxonomy_writer')");}
}
function nt_admin_status(PDO $db):array{
 $latest=$db->query('SELECT result FROM noa_classification_runs ORDER BY created_at DESC,input_hash DESC LIMIT 1')->fetchColumn();$logs=$db->query('SELECT log_id,run_id,content_type,content_id,event,result,actor,created_at FROM noa_classification_logs ORDER BY log_id DESC LIMIT 200')->fetchAll(PDO::FETCH_ASSOC);
 $review=$db->query("SELECT l.* FROM noa_classification_logs l JOIN (SELECT content_type,content_id,MAX(log_id) id FROM noa_classification_logs WHERE event IN ('review','processed','classified','unclassified') GROUP BY content_type,content_id) latest ON latest.id=l.log_id WHERE l.event='review' ORDER BY l.log_id DESC LIMIT 200")->fetchAll(PDO::FETCH_ASSOC);
 return ['relations'=>$db->query('SELECT content_type,content_id,category_id,active,revision FROM noa_content_categories')->fetchAll(PDO::FETCH_ASSOC),'categories'=>nt_categories($db),'counts'=>nt_counts($db),'rules'=>nt_rules($db),'productionRules'=>$db->query('SELECT * FROM noa_production_rules ORDER BY scope,genre_id,rule_id')->fetchAll(PDO::FETCH_ASSOC),'productionHistory'=>$db->query('SELECT rule_id,revision,sha256,actor,reason,created_at FROM noa_production_rule_revisions ORDER BY created_at DESC LIMIT 100')->fetchAll(PDO::FETCH_ASSOC),'latest'=>$latest?json_decode($latest,true):null,'review'=>$review,'logs'=>$logs];
}
